    H,W=len(g),len(g[0]); seen=[[False]*W for _ in g]; out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]:
                x=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and not seen[na][nb] and g[na][nb]==x:
                            seen[na][nb]=True; st.append((na,nb))
                out.append((x,cells))
    return out
def f(I):
    H,W=len(I),len(I[0]); cs=comps(I)
    occ=set(); res=[[0]*W for _ in range(H)]
    # processing order: unknown; try several orders
    for keyname,orderkey in [('minrow',lambda t:t[1][0]),('maxrow',lambda t:-t[1][0]),('minrowasc',lambda t:(t[1][0],t[1][1]))]:
        ordlist=sorted(cs,key=orderkey)
        done=True
        for x,cells in ordlist:
            r0=min(r for r,_ in cells); r1=max(r for r,_ in cells)
            cols=sorted(set(c for _,c in cells))
            w=cols[-1]-cols[0]+1
            shift=W-w-cols[0]   # right edge flushes? rightmost col becomes W-1
            final=[(r,c+shift) for r,c in cells]
            cols_final=[c for _,c in final]
            if max(cols_final)>=W: continue  # can't fit: skip this order
            ok=True
            for r,cc in final:
                if (r,cc) in occ: ok=False;break
                assert r<H and 0<=cc<W
            if not ok: break
        else:
            if True:
                for x,cells in ordlist:
                    cols=sorted(set(c for _,c in cells))
                    shift=W-(max(c for _,c in cells)+1)+(cols[-1])  # place rightmost col at W-1
                    for r,c in cells:
                        res[r][c+shift]=x
                        occ.add((r,c+shift))
                return res, keyname
    return None,None
